#define NUM_CHARACTER_BIOS_ZH (sizeof(CHARACTER_BIOS_ZH) / sizeof(CHARACTER_BIOS_ZH[0]))

static int cmp_character_bio_loc(const void* a, const void* b) {
    const char* key = (const char*)a;
    const struct CharacterBioLocEntry* entry = (const struct CharacterBioLocEntry*)b;
    return strcmp(key, entry->k);
}

static const char* lookup_character_bio_zh(const char* key) {
    if (!key || !*key) return NULL;
    const struct CharacterBioLocEntry* res = (const struct CharacterBioLocEntry*)bsearch(
        key,
        CHARACTER_BIOS_ZH,
        NUM_CHARACTER_BIOS_ZH,
        sizeof(struct CharacterBioLocEntry),
        cmp_character_bio_loc
    );
    if (res) return res->v;
    return NULL;
}

